// generated by build-games: content/games/<slug>.html -> bu fayl. Əl ilə dəyişmə; node scripts/build-games.mjs işlət.
export default "<!DOCTYPE html>\n<html lang=\"tr\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, user-scalable=no\">\n<title>NEON DRIVE — Premium Racer</title>\n<style>\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  html, body { width: 100%; height: 100%; overflow: hidden; background: #050508; }\n  body {\n    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;\n    touch-action: none; user-select: none; -webkit-user-select: none;\n  }\n  #wrap { position: relative; width: 100vw; height: 100vh; }\n  canvas { display: block; width: 100%; height: 100%; }\n\n  .overlay {\n    position: absolute; inset: 0; z-index: 10;\n    display: flex; flex-direction: column; align-items: center; justify-content: center;\n    background: rgba(5,5,8,.7); backdrop-filter: blur(14px);\n    transition: opacity .5s ease; text-align: center; padding: 24px;\n  }\n  .overlay.hidden { opacity: 0; pointer-events: none; }\n\n  .logo {\n    font-size: clamp(42px, 10vw, 92px); font-weight: 900; letter-spacing: .1em; font-style: italic;\n    background: linear-gradient(180deg, #fff 0%, #f43f5e 50%, #f97316 100%);\n    -webkit-background-clip: text; background-clip: text; color: transparent;\n    filter: drop-shadow(0 0 30px rgba(244,63,94,.5));\n    animation: float 3s ease-in-out infinite;\n  }\n  @keyframes float { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-9px); } }\n\n  .tagline { margin-top: 10px; color: #8b8ba3; font-size: clamp(12px, 2.4vw, 15px); letter-spacing: .35em; text-transform: uppercase; }\n\n  .btn {\n    margin-top: 40px; padding: 16px 58px; font-size: 18px; font-weight: 700;\n    letter-spacing: .2em; text-transform: uppercase; color: #050508;\n    background: linear-gradient(90deg, #f97316, #f43f5e);\n    border: none; border-radius: 999px; cursor: pointer;\n    box-shadow: 0 0 32px rgba(249,115,36,.45), 0 0 64px rgba(244,63,94,.25);\n    transition: transform .15s ease, box-shadow .15s ease;\n  }\n  .btn:hover { transform: scale(1.06); box-shadow: 0 0 48px rgba(249,115,36,.7), 0 0 96px rgba(244,63,94,.4); }\n  .btn:active { transform: scale(.97); }\n\n  .hint { margin-top: 26px; color: #55556e; font-size: 13px; letter-spacing: .08em; line-height: 1.9; }\n  .hint b { color: #9d9dbd; }\n\n  #gameover .logo {\n    background: linear-gradient(180deg, #fff 0%, #f43f5e 55%, #7c3aed 100%);\n    -webkit-background-clip: text; background-clip: text;\n  }\n  .score-big { margin-top: 16px; font-size: clamp(36px, 8vw, 62px); font-weight: 800; color: #fff; text-shadow: 0 0 24px rgba(249,115,36,.6); }\n  .score-label { color: #8b8ba3; letter-spacing: .3em; font-size: 12px; text-transform: uppercase; margin-top: 4px; }\n  #bestLine { margin-top: 10px; color: #fbbf24; font-size: 15px; letter-spacing: .15em; }\n  #newbest { display: none; margin-top: 8px; color: #4ade80; font-weight: 700; letter-spacing: .25em; font-size: 13px; animation: pulse 1s infinite; }\n  @keyframes pulse { 50% { opacity: .4; } }\n\n  #hud {\n    position: absolute; top: 0; left: 0; right: 0; z-index: 5;\n    display: flex; justify-content: space-between; align-items: flex-start;\n    padding: 18px 22px; pointer-events: none; opacity: 0; transition: opacity .4s;\n  }\n  #hud.on { opacity: 1; }\n  .hud-score { font-size: 30px; font-weight: 800; color: #fff; text-shadow: 0 0 16px rgba(249,115,36,.7); font-variant-numeric: tabular-nums; }\n  .hud-label { font-size: 10px; letter-spacing: .3em; color: #8b8ba3; text-transform: uppercase; }\n  .hud-speed { font-size: 30px; font-weight: 800; color: #fff; text-shadow: 0 0 16px rgba(34,211,238,.7); font-variant-numeric: tabular-nums; text-align: right; }\n  .hud-speed small { font-size: 12px; color: #8b8ba3; letter-spacing: .15em; }\n\n  #nitroWrap { position: absolute; bottom: 24px; left: 50%; transform: translateX(-50%); width: min(300px, 60vw); height: 8px; background: rgba(255,255,255,.08); border-radius: 99px; overflow: hidden; opacity: 0; transition: opacity .4s; z-index: 5; }\n  #nitroWrap.on { opacity: 1; }\n  #nitroBar { height: 100%; width: 100%; background: linear-gradient(90deg, #22d3ee, #a855f7); border-radius: 99px; box-shadow: 0 0 14px rgba(34,211,238,.8); transition: width .1s linear; }\n  #nitroHint { position: absolute; bottom: 38px; left: 50%; transform: translateX(-50%); color: #55556e; font-size: 10px; letter-spacing: .3em; text-transform: uppercase; opacity: 0; transition: opacity .4s; z-index: 5; }\n  #nitroHint.on { opacity: 1; }\n\n  #muteBtn { position: absolute; bottom: 16px; right: 16px; z-index: 20; background: rgba(255,255,255,.06); border: 1px solid rgba(255,255,255,.12); color: #9d9dbd; width: 44px; height: 44px; border-radius: 12px; font-size: 18px; cursor: pointer; backdrop-filter: blur(6px); }\n</style>\n</head>\n<body>\n<div id=\"wrap\">\n  <canvas id=\"game\"></canvas>\n\n  <div id=\"hud\">\n    <div>\n      <div class=\"hud-label\">Skor</div>\n      <div class=\"hud-score\" id=\"score\">0</div>\n    </div>\n    <div>\n      <div class=\"hud-label\" style=\"text-align:right\">Hız</div>\n      <div class=\"hud-speed\"><span id=\"speed\">0</span> <small>km/s</small></div>\n    </div>\n  </div>\n  <div id=\"nitroWrap\"><div id=\"nitroBar\"></div></div>\n  <div id=\"nitroHint\">Nitro: SHIFT / Yukarı / Ekrana basılı tut</div>\n\n  <div class=\"overlay\" id=\"menu\">\n    <div class=\"logo\">NEON DRIVE</div>\n    <div class=\"tagline\">Premium Yarış Deneyimi</div>\n    <button class=\"btn\" id=\"startBtn\">Sürüşe Başla</button>\n    <div class=\"hint\">\n      <b>← →</b> veya <b>A / D</b> ile şerit değiştir &nbsp;•&nbsp; <b>SHIFT / ↑</b> nitro<br>\n      Mobilde parmağını sürükle, basılı tutarak nitro yak.<br>\n      Trafiği yakından sollayarak bonus puan kazan!\n    </div>\n  </div>\n\n  <div class=\"overlay hidden\" id=\"gameover\">\n    <div class=\"logo\">KAZA!</div>\n    <div class=\"score-big\" id=\"finalScore\">0</div>\n    <div class=\"score-label\">Final Skoru</div>\n    <div id=\"bestLine\">En İyi: 0</div>\n    <div id=\"newbest\">★ YENİ REKOR ★</div>\n    <button class=\"btn\" id=\"retryBtn\">Tekrar Sür</button>\n  </div>\n\n  <button id=\"muteBtn\" title=\"Ses\">🔊</button>\n</div>\n\n<script>\n(() => {\n  \"use strict\";\n  const canvas = document.getElementById(\"game\");\n  const ctx = canvas.getContext(\"2d\");\n  let W = 0, H = 0, DPR = Math.min(window.devicePixelRatio || 1, 2);\n  function resize() {\n    W = window.innerWidth; H = window.innerHeight;\n    canvas.width = W * DPR; canvas.height = H * DPR;\n    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);\n  }\n  window.addEventListener(\"resize\", resize);\n  resize();\n\n  // ---------- SES ----------\n  let audioCtx = null, muted = false, engineOsc = null, engineGain = null;\n  function ac() {\n    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();\n    if (audioCtx.state === \"suspended\") audioCtx.resume();\n    return audioCtx;\n  }\n  function tone(freq, dur, type, vol, slide) {\n    if (muted) return;\n    try {\n      const a = ac(), o = a.createOscillator(), g = a.createGain();\n      o.type = type || \"sine\"; o.frequency.setValueAtTime(freq, a.currentTime);\n      if (slide) o.frequency.exponentialRampToValueAtTime(slide, a.currentTime + dur);\n      g.gain.setValueAtTime(vol || 0.15, a.currentTime);\n      g.gain.exponentialRampToValueAtTime(0.0001, a.currentTime + dur);\n      o.connect(g); g.connect(a.destination);\n      o.start(); o.stop(a.currentTime + dur);\n    } catch (e) {}\n  }\n  function engineStart() {\n    if (muted || engineOsc) return;\n    try {\n      const a = ac();\n      engineOsc = a.createOscillator(); engineGain = a.createGain();\n      engineOsc.type = \"sawtooth\"; engineOsc.frequency.value = 60;\n      engineGain.gain.value = 0.045;\n      engineOsc.connect(engineGain); engineGain.connect(a.destination);\n      engineOsc.start();\n    } catch (e) {}\n  }\n  function engineStop() {\n    if (engineOsc) { try { engineOsc.stop(); } catch (e) {} engineOsc = null; engineGain = null; }\n  }\n  function enginePitch(speed, nitro) {\n    if (engineOsc) engineOsc.frequency.value = 55 + speed * 0.55 + (nitro ? 40 : 0);\n  }\n  const sfx = {\n    pass: () => tone(700, 0.12, \"sine\", 0.12, 1200),\n    crash: () => { tone(120, 0.5, \"sawtooth\", 0.25, 30); tone(80, 0.6, \"square\", 0.15, 25); },\n    start: () => { tone(220, 0.15, \"sine\", 0.15, 440); setTimeout(() => tone(440, 0.2, \"sine\", 0.15, 880), 120); },\n    nitro: () => tone(300, 0.3, \"sine\", 0.1, 900),\n  };\n  document.getElementById(\"muteBtn\").addEventListener(\"click\", (e) => {\n    muted = !muted; e.target.textContent = muted ? \"🔇\" : \"🔊\";\n    if (muted) engineStop(); else if (state === STATE.PLAY) engineStart();\n  });\n\n  // ---------- DURUM ----------\n  const STATE = { MENU: 0, PLAY: 1, OVER: 2 };\n  let state = STATE.MENU;\n  let score = 0, best = +(localStorage.getItem(\"neondrive_best\") || 0);\n  let speed = 0;                 // km/s benzeri 0..220\n  let nitro = 100, nitroOn = false;\n  let shake = 0, time = 0, roadOffset = 0;\n  let playerX = 0;               // -1..1 yol üzerinde\n  let playerVX = 0, targetX = null;\n  let traffic = [], parts = [], floatTexts = [];\n\n  const LANES = 3;\n  const HORIZON = () => H * 0.32;\n\n  // perspektif: z (0=ufuk, 1=oyuncu) -> ekran\n  function project(z, x) {\n    const horizon = HORIZON();\n    const y = horizon + (1 - z) * (H - horizon) * 0.94;\n    const roadHalf = (W * 0.06) + (1 - z) * (W * 0.42);\n    return { x: W / 2 + x * roadHalf, y, scale: 0.25 + (1 - z) * 1.1, roadHalf };\n  }\n\n  function reset() {\n    score = 0; speed = 0; nitro = 100; nitroOn = false;\n    shake = 0; playerX = 0; playerVX = 0; targetX = null;\n    traffic = []; parts = []; floatTexts = [];\n    updateHUD();\n  }\n\n  function updateHUD() {\n    document.getElementById(\"score\").textContent = Math.floor(score);\n    document.getElementById(\"speed\").textContent = Math.floor(speed);\n    document.getElementById(\"nitroBar\").style.width = nitro + \"%\";\n  }\n\n  function spawnCar() {\n    const lane = Math.floor(Math.random() * LANES);\n    const laneX = (lane - (LANES - 1) / 2) * 0.62;\n    // aynı şeritte üst üste binmeyi önle\n    for (const c of traffic) if (c.lane === lane && c.z > 0.75) return;\n    const colors = [\n      [\"#22d3ee\", \"#0e7490\"], [\"#a855f7\", \"#6b21a8\"], [\"#4ade80\", \"#166534\"],\n      [\"#fbbf24\", \"#b45309\"], [\"#f472b6\", \"#9d174d\"], [\"#94a3b8\", \"#334155\"],\n    ];\n    traffic.push({\n      lane, x: laneX, z: 1.15,\n      speed: 0.28 + Math.random() * 0.2,   // göreceli yavaşlık\n      color: colors[Math.floor(Math.random() * colors.length)],\n      passed: false,\n    });\n  }\n\n  function burst(x, y, color, n, pow) {\n    for (let i = 0; i < n; i++) {\n      const a = Math.random() * Math.PI * 2, sp = (Math.random() * 0.7 + 0.3) * (pow || 4);\n      parts.push({ x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 1, life: 1, decay: 0.02 + Math.random() * 0.03, color, size: Math.random() * 4 + 1.5 });\n    }\n  }\n  function floatText(x, y, text, color) {\n    floatTexts.push({ x, y, text, color, life: 1 });\n  }\n\n  // ---------- GİRİŞ ----------\n  const keys = {};\n  window.addEventListener(\"keydown\", (e) => {\n    keys[e.key.toLowerCase()] = true;\n    if (e.key === \"Shift\" || e.key === \"ArrowUp\") keys[\"__nitro\"] = true;\n    if (state !== STATE.PLAY && (e.key === \" \" || e.key === \"Enter\")) startGame();\n  });\n  window.addEventListener(\"keyup\", (e) => {\n    keys[e.key.toLowerCase()] = false;\n    if (e.key === \"Shift\" || e.key === \"ArrowUp\") keys[\"__nitro\"] = false;\n  });\n\n  let pointerDown = false;\n  canvas.addEventListener(\"pointerdown\", (e) => { pointerDown = true; if (state === STATE.PLAY) targetX = e.clientX; });\n  canvas.addEventListener(\"pointermove\", (e) => { if (state === STATE.PLAY && pointerDown) targetX = e.clientX; });\n  window.addEventListener(\"pointerup\", () => { pointerDown = false; });\n  canvas.addEventListener(\"touchmove\", (e) => e.preventDefault(), { passive: false });\n\n  // ---------- AKIŞ ----------\n  function startGame() {\n    reset();\n    state = STATE.PLAY;\n    document.getElementById(\"menu\").classList.add(\"hidden\");\n    document.getElementById(\"gameover\").classList.add(\"hidden\");\n    document.getElementById(\"hud\").classList.add(\"on\");\n    document.getElementById(\"nitroWrap\").classList.add(\"on\");\n    document.getElementById(\"nitroHint\").classList.add(\"on\");\n    sfx.start(); engineStart();\n  }\n  function endGame() {\n    state = STATE.OVER;\n    engineStop(); sfx.crash();\n    const p = project(0, playerX);\n    burst(p.x, p.y - 30, \"#f97316\", 50, 9);\n    burst(p.x, p.y - 30, \"#f43f5e\", 40, 7);\n    burst(p.x, p.y - 30, \"#fbbf24\", 30, 6);\n    shake = 30;\n    const s = Math.floor(score);\n    const isNew = s > best;\n    if (isNew) { best = s; localStorage.setItem(\"neondrive_best\", best); }\n    document.getElementById(\"finalScore\").textContent = s;\n    document.getElementById(\"bestLine\").textContent = \"En İyi: \" + best;\n    document.getElementById(\"newbest\").style.display = isNew && s > 0 ? \"block\" : \"none\";\n    document.getElementById(\"hud\").classList.remove(\"on\");\n    document.getElementById(\"nitroWrap\").classList.remove(\"on\");\n    document.getElementById(\"nitroHint\").classList.remove(\"on\");\n    setTimeout(() => document.getElementById(\"gameover\").classList.remove(\"hidden\"), 900);\n  }\n  document.getElementById(\"startBtn\").addEventListener(\"click\", startGame);\n  document.getElementById(\"retryBtn\").addEventListener(\"click\", startGame);\n\n  // ---------- GÜNCELLE ----------\n  let spawnT = 0;\n  function update(dt) {\n    time += dt;\n\n    // Nitro\n    nitroOn = (keys[\"__nitro\"] || pointerDown && targetX == null) && nitro > 0;\n    if (pointerDown && targetX != null) nitroOn = nitro > 0 && true && pointerDown; // mobilde basılı tut = nitro\n    if (pointerDown) nitroOn = nitro > 0;\n    if (nitroOn) { nitro = Math.max(0, nitro - 28 * dt); if (nitro === 0) nitroOn = false; }\n    else nitro = Math.min(100, nitro + 9 * dt);\n\n    // Hız\n    const target = nitroOn ? 240 : 150 + Math.min(score / 30, 70);\n    speed += (target - speed) * (nitroOn ? 1.6 : 0.5) * dt;\n    enginePitch(speed, nitroOn);\n    if (nitroOn && Math.random() < 0.3) sfx.nitro();\n\n    roadOffset += speed * dt * 0.02;\n\n    // Direksiyon\n    const steer = 2.6;\n    if (keys[\"arrowleft\"] || keys[\"a\"]) { playerVX = -steer; targetX = null; }\n    else if (keys[\"arrowright\"] || keys[\"d\"]) { playerVX = steer; targetX = null; }\n    else if (targetX != null) {\n      const roadHalf = W * 0.48;\n      const want = Math.max(-1, Math.min(1, (targetX - W / 2) / roadHalf));\n      const dx = want - playerX;\n      playerVX = Math.max(-steer, Math.min(steer, dx * 8));\n      if (Math.abs(dx) < 0.02) playerVX = 0;\n    } else playerVX *= Math.exp(-8 * dt);\n    playerX = Math.max(-1.05, Math.min(1.05, playerX + playerVX * dt));\n\n    // Trafik üretimi\n    spawnT -= dt;\n    if (spawnT <= 0) {\n      spawnCar();\n      spawnT = Math.max(0.55, 1.5 - speed / 300);\n    }\n\n    // Trafik hareketi\n    const rel = speed / 220;\n    for (let i = traffic.length - 1; i >= 0; i--) {\n      const c = traffic[i];\n      c.z -= (rel - c.speed * rel) * dt * 1.35;\n      if (c.z < -0.15) { traffic.splice(i, 1); continue; }\n\n      // Yakın sollama bonusu\n      if (!c.passed && c.z < 0.12 && Math.abs(c.x - playerX) < 0.42 && Math.abs(c.x - playerX) > 0.18) {\n        c.passed = true;\n        const bonus = 25;\n        score += bonus;\n        const p = project(0.1, c.x);\n        floatText(p.x, p.y - 60, \"+\" + bonus + \" SOLAMA\", \"#4ade80\");\n        sfx.pass();\n      }\n\n      // Çarpışma\n      if (c.z < 0.09 && c.z > -0.05 && Math.abs(c.x - playerX) < 0.2) {\n        endGame();\n        return;\n      }\n    }\n\n    // Mesafe puanı\n    score += speed * dt * 0.06;\n\n    // Parçacıklar\n    for (let i = parts.length - 1; i >= 0; i--) {\n      const p = parts[i];\n      p.x += p.vx; p.y += p.vy; p.vy += 0.08; p.life -= p.decay;\n      if (p.life <= 0) parts.splice(i, 1);\n    }\n    for (let i = floatTexts.length - 1; i >= 0; i--) {\n      const t = floatTexts[i];\n      t.y -= 40 * dt; t.life -= dt * 0.8;\n      if (t.life <= 0) floatTexts.splice(i, 1);\n    }\n\n    // Nitro egzoz parçacıkları\n    if (nitroOn) {\n      const p = project(0, playerX);\n      burst(p.x, p.y - 8, Math.random() < .5 ? \"#22d3ee\" : \"#a855f7\", 2, 3);\n    }\n\n    if (shake > 0) shake *= 0.88;\n    updateHUD();\n  }\n\n  // ---------- ÇİZ ----------\n  function drawBackground() {\n    // Gökyüzü\n    const sky = ctx.createLinearGradient(0, 0, 0, HORIZON() + 2);\n    sky.addColorStop(0, \"#050508\");\n    sky.addColorStop(0.6, \"#1a0b2e\");\n    sky.addColorStop(1, \"#4c1d95\");\n    ctx.fillStyle = sky;\n    ctx.fillRect(0, 0, W, HORIZON() + 2);\n\n    // Güneş (synthwave)\n    const sunY = HORIZON() - H * 0.1;\n    const sg = ctx.createRadialGradient(W / 2, sunY, 10, W / 2, sunY, H * 0.22);\n    sg.addColorStop(0, \"rgba(249,115,36,.9)\");\n    sg.addColorStop(0.5, \"rgba(244,63,94,.5)\");\n    sg.addColorStop(1, \"rgba(244,63,94,0)\");\n    ctx.fillStyle = sg;\n    ctx.beginPath(); ctx.arc(W / 2, sunY, H * 0.22, 0, Math.PI * 2); ctx.fill();\n    ctx.fillStyle = \"#fbbf24\";\n    ctx.beginPath(); ctx.arc(W / 2, sunY, H * 0.075, 0, Math.PI * 2); ctx.fill();\n    // güneş çizgileri\n    ctx.fillStyle = \"#1a0b2e\";\n    for (let i = 0; i < 4; i++) {\n      const yy = sunY + i * 7 + Math.sin(time * 2 + i) * 1.5;\n      ctx.fillRect(W / 2 - H * 0.08, yy, H * 0.16, 2.5);\n    }\n\n    // Yıldızlar\n    ctx.fillStyle = \"rgba(255,255,255,.6)\";\n    for (let i = 0; i < 40; i++) {\n      const sx = ((i * 97.3) % 1) * W;\n      const sy = ((i * 57.7) % 1) * HORIZON() * 0.8;\n      const tw = 0.3 + 0.7 * Math.abs(Math.sin(time * 1.5 + i));\n      ctx.globalAlpha = tw * 0.7;\n      ctx.fillRect(sx, sy, 1.6, 1.6);\n    }\n    ctx.globalAlpha = 1;\n\n    // Zemin\n    const gr = ctx.createLinearGradient(0, HORIZON(), 0, H);\n    gr.addColorStop(0, \"#12081f\");\n    gr.addColorStop(1, \"#050508\");\n    ctx.fillStyle = gr;\n    ctx.fillRect(0, HORIZON(), W, H - HORIZON());\n\n    // Izgara (yan zemin)\n    ctx.strokeStyle = \"rgba(168,85,247,.18)\";\n    ctx.lineWidth = 1;\n    for (let i = 0; i < 14; i++) {\n      const z = ((i / 14 + roadOffset * 0.15) % 1);\n      const y = HORIZON() + Math.pow(z, 1.6) * (H - HORIZON());\n      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke();\n    }\n  }\n\n  function drawRoad() {\n    const horizon = HORIZON();\n    // Yol gövdesi\n    ctx.beginPath();\n    ctx.moveTo(W / 2 - W * 0.06, horizon);\n    ctx.lineTo(W / 2 + W * 0.06, horizon);\n    ctx.lineTo(W / 2 + W * 0.48, H);\n    ctx.lineTo(W / 2 - W * 0.48, H);\n    ctx.closePath();\n    const rg = ctx.createLinearGradient(0, horizon, 0, H);\n    rg.addColorStop(0, \"#1e1e2e\");\n    rg.addColorStop(1, \"#2a2a3a\");\n    ctx.fillStyle = rg;\n    ctx.fill();\n\n    // Kenar çizgileri (neon)\n    ctx.lineWidth = 3;\n    ctx.shadowBlur = 12;\n    ctx.shadowColor = \"#f43f5e\";\n    ctx.strokeStyle = \"#f43f5e\";\n    ctx.beginPath(); ctx.moveTo(W / 2 - W * 0.06, horizon); ctx.lineTo(W / 2 - W * 0.48, H); ctx.stroke();\n    ctx.shadowColor = \"#22d3ee\";\n    ctx.strokeStyle = \"#22d3ee\";\n    ctx.beginPath(); ctx.moveTo(W / 2 + W * 0.06, horizon); ctx.lineTo(W / 2 + W * 0.48, H); ctx.stroke();\n    ctx.shadowBlur = 0;\n\n    // Şerit çizgileri (hareketli)\n    for (let lane = 1; lane < LANES; lane++) {\n      const lx = (lane / LANES) * 2 - 1; // -1..1\n      for (let i = 0; i < 12; i++) {\n        const z0 = ((i / 12 + roadOffset * 0.3) % 1);\n        const z1 = Math.min(z0 + 0.03, 1);\n        const p0 = project(z0, lx * 1.0), p1 = project(z1, lx * 1.0);\n        ctx.strokeStyle = \"rgba(255,255,255,\" + (0.15 + (1 - z0) * 0.5) + \")\";\n        ctx.lineWidth = 1 + (1 - z0) * 4;\n        ctx.beginPath(); ctx.moveTo(p0.x, p0.y); ctx.lineTo(p1.x, p1.y); ctx.stroke();\n      }\n    }\n  }\n\n  function drawCar(x, y, scale, colors, isPlayer, tilt) {\n    const w = 46 * scale, h = 80 * scale;\n    ctx.save();\n    ctx.translate(x, y);\n    if (tilt) ctx.rotate(tilt);\n\n    // Gölge\n    ctx.fillStyle = \"rgba(0,0,0,.45)\";\n    ctx.beginPath(); ctx.ellipse(0, h * 0.42, w * 0.62, h * 0.12, 0, 0, Math.PI * 2); ctx.fill();\n\n    // Gövde\n    ctx.shadowColor = colors[0]; ctx.shadowBlur = isPlayer ? 22 : 10;\n    const bg = ctx.createLinearGradient(0, -h / 2, 0, h / 2);\n    bg.addColorStop(0, colors[0]);\n    bg.addColorStop(1, colors[1]);\n    ctx.fillStyle = bg;\n    roundRect(-w / 2, -h / 2, w, h, w * 0.28);\n    ctx.fill();\n    ctx.shadowBlur = 0;\n\n    // Cam\n    ctx.fillStyle = \"rgba(10,10,20,.85)\";\n    roundRect(-w * 0.32, -h * 0.22, w * 0.64, h * 0.3, w * 0.12);\n    ctx.fill();\n    // Arka cam\n    roundRect(-w * 0.28, h * 0.18, w * 0.56, h * 0.14, w * 0.08);\n    ctx.fill();\n\n    // Farlar / stoplar\n    if (isPlayer) {\n      ctx.fillStyle = \"#ff2d55\";\n      ctx.shadowColor = \"#ff2d55\"; ctx.shadowBlur = 14;\n      roundRect(-w * 0.4, h * 0.4, w * 0.24, h * 0.06, 3); ctx.fill();\n      roundRect(w * 0.16, h * 0.4, w * 0.24, h * 0.06, 3); ctx.fill();\n      ctx.shadowBlur = 0;\n      // Nitro alevi\n      if (nitroOn) {\n        const fl = 18 + Math.sin(time * 40) * 7;\n        const fg = ctx.createLinearGradient(0, h / 2, 0, h / 2 + fl);\n        fg.addColorStop(0, \"rgba(34,211,238,.95)\");\n        fg.addColorStop(1, \"rgba(168,85,247,0)\");\n        ctx.fillStyle = fg;\n        ctx.beginPath();\n        ctx.moveTo(-w * 0.25, h / 2); ctx.lineTo(0, h / 2 + fl + 8); ctx.lineTo(w * 0.25, h / 2);\n        ctx.closePath(); ctx.fill();\n      }\n    } else {\n      ctx.fillStyle = \"#fef08a\";\n      ctx.shadowColor = \"#fde047\"; ctx.shadowBlur = 10;\n      roundRect(-w * 0.4, -h * 0.46, w * 0.22, h * 0.05, 3); ctx.fill();\n      roundRect(w * 0.18, -h * 0.46, w * 0.22, h * 0.05, 3); ctx.fill();\n      ctx.shadowBlur = 0;\n    }\n    ctx.restore();\n  }\n\n  function roundRect(x, y, w, h, r) {\n    ctx.beginPath();\n    ctx.moveTo(x + r, y);\n    ctx.arcTo(x + w, y, x + w, y + h, r);\n    ctx.arcTo(x + w, y + h, x, y + h, r);\n    ctx.arcTo(x, y + h, x, y, r);\n    ctx.arcTo(x, y, x + w, y, r);\n    ctx.closePath();\n  }\n\n  function draw() {\n    ctx.clearRect(0, 0, W, H);\n    ctx.save();\n    if (shake > 0.5) ctx.translate((Math.random() - .5) * shake, (Math.random() - .5) * shake);\n\n    drawBackground();\n    drawRoad();\n\n    // Trafik (uzaktan yakına)\n    const sorted = [...traffic].sort((a, b) => b.z - a.z);\n    for (const c of sorted) {\n      const p = project(c.z, c.x);\n      drawCar(p.x, p.y, p.scale, c.color, false, 0);\n    }\n\n    // Oyuncu\n    if (state === STATE.PLAY || state === STATE.MENU) {\n      const p = project(0, state === STATE.MENU ? Math.sin(time * 0.7) * 0.4 : playerX);\n      const tilt = state === STATE.PLAY ? playerVX * 0.06 : Math.cos(time * 0.7) * 0.03;\n      drawCar(p.x, p.y - 10, 1.15, [\"#f43f5e\", \"#7f1d3a\"], true, tilt);\n    }\n\n    // Parçacıklar\n    for (const p of parts) {\n      ctx.globalAlpha = Math.max(p.life, 0);\n      ctx.fillStyle = p.color;\n      ctx.beginPath(); ctx.arc(p.x, p.y, p.size * p.life, 0, Math.PI * 2); ctx.fill();\n    }\n    ctx.globalAlpha = 1;\n\n    // Yüzen yazılar\n    for (const t of floatTexts) {\n      ctx.globalAlpha = Math.max(t.life, 0);\n      ctx.font = \"800 18px 'Segoe UI', sans-serif\";\n      ctx.fillStyle = t.color;\n      ctx.textAlign = \"center\";\n      ctx.shadowColor = t.color; ctx.shadowBlur = 12;\n      ctx.fillText(t.text, t.x, t.y);\n      ctx.shadowBlur = 0;\n    }\n    ctx.globalAlpha = 1;\n\n    ctx.restore();\n\n    // Hız çizgileri (nitro)\n    if (state === STATE.PLAY && speed > 180) {\n      ctx.strokeStyle = \"rgba(255,255,255,\" + Math.min((speed - 180) / 120, 0.35) + \")\";\n      ctx.lineWidth = 2;\n      for (let i = 0; i < 10; i++) {\n        const a = Math.random() * Math.PI * 2, r = Math.min(W, H) * (0.35 + Math.random() * 0.3);\n        const x = W / 2 + Math.cos(a) * r, y = H / 2 + Math.sin(a) * r;\n        ctx.beginPath();\n        ctx.moveTo(x, y);\n        ctx.lineTo(x + Math.cos(a) * 40, y + Math.sin(a) * 40);\n        ctx.stroke();\n      }\n    }\n\n    // Vinyet\n    const v = ctx.createRadialGradient(W / 2, H / 2, Math.min(W, H) * 0.35, W / 2, H / 2, Math.max(W, H) * 0.78);\n    v.addColorStop(0, \"rgba(0,0,0,0)\");\n    v.addColorStop(1, \"rgba(0,0,0,.55)\");\n    ctx.fillStyle = v;\n    ctx.fillRect(0, 0, W, H);\n  }\n\n  // ---------- DÖNGÜ ----------\n  let last = performance.now();\n  function loop(now) {\n    const dt = Math.min((now - last) / 1000, 0.05);\n    last = now;\n    if (state === STATE.PLAY) update(dt);\n    else { time += dt; roadOffset += dt * 0.4; }\n    draw();\n    requestAnimationFrame(loop);\n  }\n  requestAnimationFrame(loop);\n})();\n</script>\n</body>\n</html>\n";
